mapper.select:
SELECT f.festival_id, f.category_id, f.location_id, f.festival_nm, fd.year FROM festival f LEFT JOIN festival_detail fd ON f.festival_id = fd.festival_id WHERE f.location_id = #{locationId}
AND f.category_id IN
#{categoryId}
ORDER BY f.festival_nm, fd.year

SELECT COALESCE(SUM(fd.total_visitors), 0) as totalVisitors, COALESCE(AVG(fd.total_visitors), 0) as avgVisitors, COALESCE(SUM(fd.gross_sales), 0) as totalSales, COALESCE(AVG(fd.gross_sales), 0) as avgSales, COUNT(DISTINCT f.festival_id) as festivalCount, COUNT(DISTINCT fd.year) as yearCount FROM festival f LEFT JOIN festival_detail fd ON f.festival_id = fd.festival_id WHERE 1=1
AND f.festival_nm IN
#{festivalName}
AND fd.year IN
#{year}

SELECT f.festival_id as festivalId, f.festival_nm as festivalName, fd.total_visitors as totalVisitors, fd.avg_daily_visitors as avgDailyVisitors, fd.budget_krw as budgetKrw, fd.year as year, fd.gross_sales as grossSales, fd.promo_intensity_index as promoIntensityIndex, fd.lodging_visitor_ratio as lodgingVisitorRatio FROM festival f LEFT JOIN festival_detail fd ON f.festival_id = fd.festival_id WHERE 1=1
AND f.festival_nm IN
#{festivalName}
AND fd.year IN
#{year}
ORDER BY f.festival_nm, fd.year
